CREATE OR REPLACE FUNCTION public.create_manual_student_for_term_v1(p_academic_term_id integer, p_student_number text, p_first_name text, p_last_name text, p_email text, p_program text, p_year_level integer, p_is_shs boolean DEFAULT false, p_photo_url text DEFAULT NULL::text, p_precinct_code text DEFAULT NULL::text, p_batch_code text DEFAULT NULL::text)
 RETURNS TABLE(outcome text, student_id integer, student_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  normalized_student_number text := trim(coalesce(p_student_number, ''));
  normalized_first_name text := trim(coalesce(p_first_name, ''));
  normalized_last_name text := trim(coalesce(p_last_name, ''));
  normalized_email text := lower(nullif(trim(coalesce(p_email, '')), ''));
  normalized_program text := upper(trim(coalesce(p_program, '')));
  created_student_id integer;
  violated_constraint text;
begin
  if normalized_student_number !~ '^[0-9]{5}$' then
    outcome := 'INVALID_FORMAT';
    student_id := null;
    student_status := null;
    return next;
    return;
  end if;

  if normalized_first_name = ''
    or normalized_last_name = ''
    or normalized_program = ''
    or (normalized_email is not null and position('@' in normalized_email) <= 1)
    or p_year_level is null
    or p_year_level < 1
    or p_year_level > 6 then
    outcome := 'INVALID_INPUT';
    student_id := null;
    student_status := null;
    return next;
    return;
  end if;

  if not exists (
    select 1
    from public.academic_terms at
    where at.id = p_academic_term_id
      and at.status = 'active'
  ) then
    outcome := 'INVALID_TERM';
    student_id := null;
    student_status := null;
    return next;
    return;
  end if;

  begin
    insert into public.students (
      student_number,
      first_name,
      last_name,
      email,
      photo_url,
      program,
      year_level,
      precinct_code,
      batch_code,
      is_shs,
      status
    )
    values (
      normalized_student_number,
      normalized_first_name,
      normalized_last_name,
      normalized_email,
      nullif(trim(coalesce(p_photo_url, '')), ''),
      normalized_program,
      p_year_level,
      nullif(trim(coalesce(p_precinct_code, '')), ''),
      nullif(trim(coalesce(p_batch_code, '')), ''),
      coalesce(p_is_shs, false),
      'pending'
    )
    returning id into created_student_id;

    insert into public.student_term_enrollments (
      student_id,
      academic_term_id,
      program,
      year_level,
      is_shs,
      enrollment_status,
      source
    )
    values (
      created_student_id,
      p_academic_term_id,
      normalized_program,
      p_year_level,
      coalesce(p_is_shs, false),
      'enrolled',
      'manual'
    );
  exception
    when unique_violation then
      get stacked diagnostics violated_constraint = constraint_name;

      if violated_constraint = 'students_student_number_key' then
        outcome := 'IDENTITY_RECHECK_REQUIRED';
      elsif violated_constraint = 'student_term_enrollments_unique_student_term' then
        outcome := 'ALREADY_ENROLLED_CURRENT_TERM';
      else
        outcome := 'SAFE_SERVER_ERROR';
      end if;

      student_id := null;
      student_status := null;
      return next;
      return;
    when others then
      outcome := 'SAFE_SERVER_ERROR';
      student_id := null;
      student_status := null;
      return next;
      return;
  end;

  outcome := 'NEW_STUDENT_CREATED';
  student_id := created_student_id;
  student_status := 'pending';
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.enroll_existing_student_for_term_v1(p_student_id integer, p_academic_term_id integer, p_program text, p_year_level integer, p_is_shs boolean DEFAULT false)
 RETURNS TABLE(outcome text, student_id integer, student_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  normalized_program text := upper(trim(coalesce(p_program, '')));
  existing_status text;
  existing_enrollment_id integer;
  existing_enrollment_status text;
  enrollment_found boolean := false;
begin
  if p_student_id is null
    or p_student_id <= 0
    or normalized_program = ''
    or p_year_level is null
    or p_year_level < 1
    or p_year_level > 6 then
    outcome := 'INVALID_INPUT';
    student_id := null;
    student_status := null;
    return next;
    return;
  end if;

  if not exists (
    select 1
    from public.academic_terms at
    where at.id = p_academic_term_id
      and at.status = 'active'
  ) then
    outcome := 'INVALID_TERM';
    student_id := null;
    student_status := null;
    return next;
    return;
  end if;

  select s.status
  into existing_status
  from public.students s
  where s.id = p_student_id
  for update;

  if not found then
    outcome := 'IDENTITY_RECHECK_REQUIRED';
    student_id := null;
    student_status := null;
    return next;
    return;
  end if;

  select ste.id, ste.enrollment_status
  into existing_enrollment_id, existing_enrollment_status
  from public.student_term_enrollments ste
  where ste.student_id = p_student_id
    and ste.academic_term_id = p_academic_term_id
  for update;

  enrollment_found := found;

  if enrollment_found and existing_enrollment_status = 'enrolled' then
    outcome := 'ALREADY_ENROLLED_CURRENT_TERM';
    student_id := p_student_id;
    student_status := existing_status;
    return next;
    return;
  end if;

  if enrollment_found and existing_enrollment_status <> 'not_in_masterlist' then
    outcome := 'SAFE_SERVER_ERROR';
    student_id := null;
    student_status := null;
    return next;
    return;
  end if;

  begin
    if existing_enrollment_id is null then
    insert into public.student_term_enrollments (
      student_id,
      academic_term_id,
      program,
      year_level,
      is_shs,
      enrollment_status,
      source
    )
    values (
      p_student_id,
      p_academic_term_id,
      normalized_program,
      p_year_level,
      coalesce(p_is_shs, false),
      'enrolled',
      'manual'
      );

      outcome := 'EXISTING_STUDENT_ENROLLED';
    else
      update public.student_term_enrollments
      set program = normalized_program,
          year_level = p_year_level,
          is_shs = coalesce(p_is_shs, false),
          enrollment_status = 'enrolled',
          updated_at = now()
      where id = existing_enrollment_id;

      outcome := 'EXISTING_STUDENT_TERM_RESTORED';
    end if;
  exception
    when unique_violation then
      outcome := 'ALREADY_ENROLLED_CURRENT_TERM';
      student_id := p_student_id;
      student_status := existing_status;
      return next;
      return;
    when others then
      outcome := 'SAFE_SERVER_ERROR';
      student_id := null;
      student_status := null;
      return next;
      return;
  end;

  student_id := p_student_id;
  student_status := existing_status;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_masterlist_import(target_import_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  target_term_id integer;
  target_scope text;
  current_import_status text;
  current_term_status text;
  actual_total integer;
  actual_invalid integer;
  actual_conflicts integer;
  actual_pending integer;
  actual_unapproved_shifted integer;
  r record;
  resolved_student_id integer;
begin
  select mi.academic_term_id, mi.import_scope, mi.import_status, at.status
    into target_term_id, target_scope, current_import_status, current_term_status
  from public.masterlist_imports mi
  join public.academic_terms at on at.id = mi.academic_term_id
  where mi.id = target_import_id
  for update of mi;
  if target_term_id is null then
    raise exception 'Masterlist import % does not exist.', target_import_id;
  end if;
  if target_scope is null or target_scope not in ('incremental', 'full_roster') then
    raise exception using errcode = '22023', message = 'Masterlist import scope is missing or unknown.';
  end if;
  if current_import_status <> 'review' then
    raise exception 'Masterlist import % must be in review status before finalization. Current status: %.', target_import_id, current_import_status;
  end if;
  if current_term_status = 'closed' then
    raise exception 'Cannot finalize a masterlist for a closed academic term.';
  end if;

  select count(*), count(*) filter (where reconciliation_status = 'invalid'),
    count(*) filter (where reconciliation_status = 'conflict'),
    count(*) filter (where reconciliation_status = 'pending'),
    count(*) filter (where reconciliation_status = 'shifted_program' and review_status <> 'approved')
  into actual_total, actual_invalid, actual_conflicts, actual_pending, actual_unapproved_shifted
  from public.masterlist_import_rows where import_id = target_import_id;
  if actual_total = 0 then raise exception 'Cannot finalize an empty masterlist import.'; end if;
  if actual_pending > 0 then
    raise exception 'Cannot finalize masterlist import %. % row(s) are still pending reconciliation.', target_import_id, actual_pending;
  end if;
  if actual_invalid > 0 then raise exception 'Cannot finalize masterlist import %. % invalid row(s) must be resolved first.', target_import_id, actual_invalid; end if;
  if actual_conflicts > 0 then raise exception 'Cannot finalize masterlist import %. % conflict row(s) must be resolved first.', target_import_id, actual_conflicts; end if;
  if actual_unapproved_shifted > 0 then raise exception 'Cannot finalize masterlist import %. % shifted program row(s) require approval first.', target_import_id, actual_unapproved_shifted; end if;

  for r in
    select * from public.masterlist_import_rows
    where import_id = target_import_id
      and reconciliation_status in ('new', 'continuing', 'shifted_program', 'returnee')
    order by row_number
  loop
    resolved_student_id := null;
    if r.reconciliation_status = 'new' then
      insert into public.students (student_number, first_name, last_name, email, program, year_level, is_shs, status)
      values (trim(r.student_number), trim(r.first_name), trim(r.last_name), nullif(trim(r.email), ''), r.program, r.year_level, r.is_shs, 'pending')
      returning id into resolved_student_id;
      update public.masterlist_import_rows set matched_student_id = resolved_student_id where id = r.id;
    else
      resolved_student_id := r.matched_student_id;
      if resolved_student_id is null then
        raise exception 'Row % is classified as % but has no matched student.', r.row_number, r.reconciliation_status;
      end if;
    end if;

    insert into public.student_term_enrollments (student_id, academic_term_id, program, year_level, is_shs, enrollment_status, source)
    values (resolved_student_id, target_term_id, r.program, r.year_level, r.is_shs, 'enrolled', 'masterlist')
    on conflict (student_id, academic_term_id) do update set
      program = excluded.program, year_level = excluded.year_level, is_shs = excluded.is_shs,
      enrollment_status = 'enrolled', source = 'masterlist', updated_at = now();
  end loop;

  update public.masterlist_imports
  set import_status = 'finalized', finalized_at = now(), total_rows = actual_total,
      invalid_rows = actual_invalid, conflict_rows = actual_conflicts
  where id = target_import_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.kandid_super_admin_list_students(p_actor_admin_id bigint, p_search text DEFAULT NULL::text, p_status text DEFAULT 'all'::text, p_student_ids integer[] DEFAULT NULL::integer[], p_sort text DEFAULT 'name_asc'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  search_text text := pg_catalog.btrim(coalesce(p_search, ''));
  escaped_search text;
  normalized_status text := coalesce(p_status, 'all');
  normalized_sort text := coalesce(p_sort, 'name_asc');
  page_number integer := greatest(coalesce(p_page, 1), 1);
  page_limit integer := least(greatest(coalesce(p_page_size, 10), 1), 250);
  row_offset bigint;
  total_rows bigint;
  rows_json jsonb;
begin
  if not exists (
    select 1 from public.admin_users a
    where a.id = p_actor_admin_id and a.role = 'super_admin' and a.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'Active Super Admin authorization is required.';
  end if;
  if normalized_status not in ('all', 'pending', 'active', 'disabled') then
    raise exception using errcode = '22023', message = 'Student status filter is invalid.';
  end if;
  if normalized_sort not in ('name_asc', 'name_desc', 'newest', 'oldest', 'id_asc', 'id_desc') then
    raise exception using errcode = '22023', message = 'Student sort option is invalid.';
  end if;
  if pg_catalog.cardinality(p_student_ids) > 50000 then
    raise exception using errcode = '22023', message = 'Student filter contains too many records.';
  end if;
  escaped_search := pg_catalog.replace(pg_catalog.replace(pg_catalog.replace(search_text, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_');
  row_offset := (page_number::bigint - 1) * page_limit;

  with filtered as (
    select s.id, s.student_number, s.first_name, s.last_name, s.email,
           s.photo_url, s.program, s.year_level, s.precinct_code,
           s.batch_code, s.status, s.created_at
    from public.students s
    where (normalized_status = 'all' or s.status = normalized_status)
      and (p_student_ids is null or s.id = any(p_student_ids))
      and (search_text = '' or
        s.student_number ilike '%' || escaped_search || '%' escape E'\\' or
        s.first_name ilike '%' || escaped_search || '%' escape E'\\' or
        s.last_name ilike '%' || escaped_search || '%' escape E'\\' or
        coalesce(s.email, '') ilike '%' || escaped_search || '%' escape E'\\')
  ),
  counted as (select pg_catalog.count(*)::bigint as total from filtered),
  ordered as (
    select filtered.*,
      pg_catalog.row_number() over (
        order by
          case when normalized_sort = 'name_asc' then pg_catalog.lower(filtered.last_name) end asc nulls last,
          case when normalized_sort = 'name_desc' then pg_catalog.lower(filtered.last_name) end desc nulls last,
          case when normalized_sort = 'name_asc' then pg_catalog.lower(filtered.first_name) end asc nulls last,
          case when normalized_sort = 'name_desc' then pg_catalog.lower(filtered.first_name) end desc nulls last,
          case when normalized_sort = 'newest' then filtered.created_at end desc nulls last,
          case when normalized_sort = 'oldest' then filtered.created_at end asc nulls last,
          case when normalized_sort = 'id_asc' then filtered.student_number end asc nulls last,
          case when normalized_sort = 'id_desc' then filtered.student_number end desc nulls last,
          filtered.id asc
      ) as row_order
    from filtered
  ),
  page_rows as (
    select * from ordered where row_order > row_offset and row_order <= row_offset + page_limit
  )
  select counted.total,
         coalesce((select pg_catalog.jsonb_agg(
           pg_catalog.jsonb_build_object(
             'id', p.id, 'student_number', p.student_number,
             'first_name', p.first_name, 'last_name', p.last_name,
             'email', p.email, 'photo_url', p.photo_url, 'program', p.program,
             'year_level', p.year_level, 'precinct_code', p.precinct_code,
             'batch_code', p.batch_code, 'status', p.status, 'created_at', p.created_at
           ) order by p.row_order
         ) from page_rows p), '[]'::jsonb)
    into total_rows, rows_json
  from counted;

  return pg_catalog.jsonb_build_object('total_count', total_rows, 'data', rows_json);
end;
$function$

CREATE OR REPLACE FUNCTION public.kandid_super_admin_update_student(p_actor_admin_id bigint, p_student_id integer, p_student jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  actor_row public.admin_users%rowtype;
  original_row public.students%rowtype;
  saved_row public.students%rowtype;
  allowed_keys text[] := array[
    'student_number', 'first_name', 'last_name', 'email', 'photo_url',
    'program', 'year_level', 'precinct_code', 'batch_code', 'status'
  ];
  changed_fields text[] := array[]::text[];
begin
  select a.* into actor_row
  from public.admin_users a
  where a.id = p_actor_admin_id
    and a.role = 'super_admin'
    and a.status = 'active';
  if not found then
    raise exception using errcode = '42501', message = 'Active Super Admin authorization is required.';
  end if;
  if p_student_id is null or jsonb_typeof(p_student) <> 'object' then
    raise exception using errcode = '22023', message = 'A student record and update object are required.';
  end if;
  if exists (
    select 1 from pg_catalog.jsonb_object_keys(p_student) as keys(key_name)
    where not (keys.key_name = any (allowed_keys))
  ) then
    raise exception using errcode = '22023', message = 'The update contains unsupported student fields.';
  end if;
  if nullif(pg_catalog.btrim(p_student->>'student_number'), '') is null
     or nullif(pg_catalog.btrim(p_student->>'first_name'), '') is null
     or nullif(pg_catalog.btrim(p_student->>'last_name'), '') is null
     or nullif(pg_catalog.btrim(p_student->>'program'), '') is null
     or nullif(p_student->>'year_level', '') is null
     or coalesce(p_student->>'status', '') not in ('pending', 'active', 'disabled') then
    raise exception using errcode = '22023', message = 'Student identity, academic fields, and status are required.';
  end if;
  if p_student->>'student_number' !~ '^[0-9]{5}$' then
    raise exception using errcode = '22023', message = 'Student Number must contain five digits.';
  end if;
  if coalesce(p_student->>'email', '') <> '' and p_student->>'email' !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception using errcode = '22023', message = 'Enter a valid email address.';
  end if;
  if p_student->>'year_level' !~ '^[0-9]+$' then
    raise exception using errcode = '22023', message = 'Year level must be a whole number.';
  end if;
  if coalesce(p_student->>'email', '') <> '' and exists (
    select 1 from public.admin_users a
    where pg_catalog.lower(pg_catalog.btrim(a.email)) = pg_catalog.lower(pg_catalog.btrim(p_student->>'email'))
  ) then
    raise exception using errcode = '22023', message = 'This email address is already assigned to an administrator account.';
  end if;
  if p_student->>'status' = 'active' and coalesce(p_student->>'email', '') <> '' and exists (
    select 1 from public.students other_student
    where other_student.id <> p_student_id
      and other_student.status = 'active'
      and pg_catalog.lower(pg_catalog.btrim(other_student.email)) = pg_catalog.lower(pg_catalog.btrim(p_student->>'email'))
  ) then
    raise exception using errcode = '22023', message = 'This email address is already assigned to another active student.';
  end if;

  select s.* into original_row
  from public.students s
  where s.id = p_student_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Student record was not found.';
  end if;

  update public.students s
  set student_number = pg_catalog.btrim(p_student->>'student_number'),
      first_name = pg_catalog.btrim(p_student->>'first_name'),
      last_name = pg_catalog.btrim(p_student->>'last_name'),
      email = nullif(pg_catalog.lower(pg_catalog.btrim(p_student->>'email')), ''),
      photo_url = nullif(p_student->>'photo_url', ''),
      program = pg_catalog.btrim(p_student->>'program'),
      year_level = (p_student->>'year_level')::integer,
      precinct_code = nullif(pg_catalog.btrim(p_student->>'precinct_code'), ''),
      batch_code = nullif(pg_catalog.btrim(p_student->>'batch_code'), ''),
      status = p_student->>'status'
  where s.id = p_student_id
  returning s.* into saved_row;

  if original_row.student_number is distinct from saved_row.student_number then changed_fields := pg_catalog.array_append(changed_fields, 'student_number'); end if;
  if original_row.first_name is distinct from saved_row.first_name then changed_fields := pg_catalog.array_append(changed_fields, 'first_name'); end if;
  if original_row.last_name is distinct from saved_row.last_name then changed_fields := pg_catalog.array_append(changed_fields, 'last_name'); end if;
  if original_row.email is distinct from saved_row.email then changed_fields := pg_catalog.array_append(changed_fields, 'email'); end if;
  if original_row.photo_url is distinct from saved_row.photo_url then changed_fields := pg_catalog.array_append(changed_fields, 'photo_url'); end if;
  if original_row.program is distinct from saved_row.program then changed_fields := pg_catalog.array_append(changed_fields, 'program'); end if;
  if original_row.year_level is distinct from saved_row.year_level then changed_fields := pg_catalog.array_append(changed_fields, 'year_level'); end if;
  if original_row.precinct_code is distinct from saved_row.precinct_code then changed_fields := pg_catalog.array_append(changed_fields, 'precinct_code'); end if;
  if original_row.batch_code is distinct from saved_row.batch_code then changed_fields := pg_catalog.array_append(changed_fields, 'batch_code'); end if;
  if original_row.status is distinct from saved_row.status then changed_fields := pg_catalog.array_append(changed_fields, 'status'); end if;

  insert into public.audit_logs (
    user_id, actor_name, actor_role, action, event_type, event_category,
    entity_type, entity_id, entity_label, status, event_origin, metadata
  ) values (
    actor_row.id, actor_row.full_name, actor_row.role,
    'student_updated', 'student_updated', public.kandid_audit_category_for_event('student_updated'),
    'student', p_student_id::text, 'Student #' || p_student_id::text,
    'completed', 'trusted_server',
    pg_catalog.jsonb_build_object('changed_fields', to_jsonb(changed_fields))
  );

  return pg_catalog.to_jsonb(saved_row) - 'password' - 'auth_user_id';
end;
$function$

